// TH15 v1.00b st02.ecl.txt
// Entry: MainSub02 993-1007 (three rounds x nine mirrored Phantom01R pairs).
// Dependencies: Phantom01R 1205-1212, Phantom01 1176-1194, Phantom01_at 1214-1234.
// Death callback PhantomDeadAttack1/Et1 (1318-1347) is not executed: the training
// shell keeps both real enemies invulnerable, so the source death shots cannot fire.

const TIME_LIMIT: int = 2324;
const OPENING_BUFFER: int = 120;

// etSprite(0, 7, 2): TH15 type 7 maps to the existing modern slot, base radius 4.
const TH15_RING_BALL2: int = 464;

// MainSub02 1000: %A = %A + _f(16) -> 16px column spacing.
const COLUMN_STEP: fx = 16fx;

// Phantom01_at 1214-1234: etAim(0), one way, difficulty-selected layers/speeds.
// A = diffI($A,1,1,2,3); etCountD layers E1/N2/H4/L8; etSpeedD (1,1)/(2,0.8)/(3,1)/(4,1).
async sub shooter(shots: int, layers: int, s0: fx, s1: fx) {
    var left: int = shots;
    while left > 0 {
        // 1229: wait(20 + ($RAND % 200))
        wait(20 + rand(200));
        // 1218: etAim(0,0) takes one player-aim sample for the whole wave.
        var aim: angle = aim_player();
        var step: fx = 0fx;
        if layers > 1 { step = (s1 - s0) / (layers - 1); }
        for q in 0..layers {
            var v: fx = s0 + step * (q as fx);
            // 1224 EX ANIM a=1 keeps the birth retreat position -= 4*velocity.
            _ = fire(TH15_RING_BALL2, 2,
                     $self_x - 4fx * v * cos(aim),
                     $self_y - 4fx * v * sin(aim),
                     v, aim, none, none);
        }
        left = left - 1;
    }
}

// Phantom01R 1205-1212 -> Phantom01 1176-1194.
async sub phantom(x0: fx) {
    // Invulnerable training shell for the real enemy; source boxes kept.
    set_invuln(65535);
    set_hurtbox(14fx);   // 1178 setHurtbox(28,28): ordinary circle uses 28/2
    set_hitbox(8fx);     // 1179 setHitbox(16,16): 16/2
    // 1180 flagSet(12) disables source offscreen recycling (bits 0x4|0x8);
    // the target has no enemy-side switch. Observed target behaviour: enemies
    // spawned at y=-24 are kept and are recycled only below the screen.

    // 1226 diffI($A,1,1,2,3) and the two difficulty-selected emitter tables.
    var rank: int = global(GVAR_RANK);
    var shots: int = 1;
    var layers: int = 1;
    var s0: fx = 1fx;
    var s1: fx = 1fx;
    if rank == 1 { layers = 2; s0 = 2fx; s1 = 0.8fx; }
    if rank == 2 { shots = 2; layers = 4; s0 = 3fx; s1 = 1fx; }
    if rank == 3 { shots = 3; layers = 8; s0 = 4fx; s1 = 1fx; }

    // 1181-1182 moveVel(pi/2,0.5) then moveVelTime(120, mode3, pi/2, 1.0):
    // ABS falls with speed 0.5 -> 1.0 (quartic ease-in) over 120 frames.
    var ax: fx = x0;          // ABS layer x (never changes)
    var ay: fx = -24fx;       // ABS layer y
    var speed: fx = 0.5fx;
    // 1183 moveEllipseRel(F0=0, 2deg/frame, r=10, d=0, axis=%ABS_ANGLE=90deg, s=0):
    // degenerates to the fixed-axis sine offset +10*cos(theta) on x.
    var theta: angle = 0deg;
    var relx: fx = 10fx;
    var k: int = 0;
    move_to(0, ax + relx, ay, EASE_LINEAR);   // REL setter applies +10 on the setup frame

    spawn shooter(shots, layers, s0, s1);     // 1184 @Phantom01_at() async

    loop {
        k = k + 1;
        if k <= 120 {
            var t: fx = (k as fx) / 120fx;
            speed = 0.5fx + 0.5fx * (t * t) * (t * t);
        } else {
            speed = 1fx;
        }
        ay = ay + speed;
        theta = theta + 2deg;
        relx = 10fx * cos(theta);
        // REL is a separate source layer; final position is ABS + REL.
        move_to(0, ax + relx, ay, EASE_LINEAR);
        wait(1);
    }
}

// MainSub02 993-1007: D=3 rounds; each round nine pairs, 30 frames apart.
async sub pattern() {
    wait(OPENING_BUFFER);
    for r in 0..3 {
        var a: fx = 0fx;
        for j in 0..9 {
            a = a + COLUMN_STEP;
            _ = spawn_enemy(a, -24fx, 100, 0, 0, 0, phantom(a));
            // 1002 enmCreateM 负x: the source mirror bit has no effect on the
            // vertical ABS motion or on the unmirrored ellipse REL setter.
            _ = spawn_enemy(0fx - a, -24fx, 100, 0, 0, 0, phantom(0fx - a));
            wait(30);
        }
    }
    loop { wait(1); }
}

async sub control() {
    set_invuln(65535);
    set_enemy_flag(ENEMY_NO_BODY, 1);
    phase_begin(0, pattern, TIME_LIMIT, 0);
    wait_spell();
    loop { wait(1); }
}

sub main() {
    _ = spawn_enemy(0fx, 0fx, 1000, 0, 0, 0, control);
    loop { wait(600); }
}
